import{_ as o,l as t,o as e,c as r,v as i,p as l,x as s,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"Windows NT 对照","description":"","frontmatter":{"title":"Windows NT 对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/windows-nt-contrast.md","filePath":"cs/windows-nt-contrast.md","lastUpdated":1789023840000}'),h={name:"cs/windows-nt-contrast.md"};function u(T,a,_,m,N,f){const n=t("Mermaid");return e(),r("div",null,[a[1]||(a[1]=i('<h1 id="windows-nt-对照" tabindex="-1">Windows NT 对照 <a class="header-anchor" href="#windows-nt-对照" aria-label="Permalink to &quot;Windows NT 对照&quot;">​</a></h1><div class="epigraph"><p>NT 用对象管理器统一进程、文件、设备：句柄表、I/O 请求包 IRP、注册表，而不是「一切皆 Unix 文件描述符」的同一套。</p><footer>—— 据 Russinovich, Solomon, Ionescu, <em>Windows Internals</em>；[VFS](/cs/vfs) 与 [设备模型](/cs/device-model-binding) 为 Linux 侧先修</footer></div><p><a href="/cs/rust-in-kernel">Rust in kernel</a> 仍在 Linux。课程序列需要 <strong>对照</strong>：同一问题 NT 如何切对象。不是教你写 NT 驱动教程。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>句柄：带访问权的对象指针。IRP：异步 I/O 的统一包，类似 bio+skb 的职务在 I/O 管理器。缺口：NT 命名空间 <code>\\Device\\...</code> vs Unix <code>/dev</code>；作业对象约等于 job≈cgroup 亲戚。本课不把 Win32 与 NT 原生 API 的每一层写完。</p><p><span class="marginnote">Hyper-V 类型 1 与 NT 的关系：NT 可当根分区。对象是内核架构对照。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照表只点：调度（优先级+量子 vs CFS/EEVDF）、内存（工作集 vs RSS/memcg）、文件（NTFS vs ext4 已在 FS 课）、网络（NDIS vs sk_buff）。对照 <a href="/cs/linux-capabilities">capabilities</a>：NT 是 ACL+特权。对照 <a href="/cs/chardev-ioctl">ioctl</a>：DeviceIoControl/IRP_MJ_DEVICE_CONTROL。</p>',8)),(e(),l(p,null,{default:s(()=>[c(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBJ%5B%22NT%20%E5%AF%B9%E8%B1%A1%E7%AE%A1%E7%90%86%E5%99%A8%22%5D%20--%3E%20H%5B%22%E5%8F%A5%E6%9F%84%22%5D%0A%20%20IO%5B%22I%2FO%20%E7%AE%A1%E7%90%86%E5%99%A8%22%5D%20--%3E%20IRP%5B%22IRP%22%5D%0A%20%20IRP%20--%3E%20DRV%5B%22%E9%A9%B1%E5%8A%A8%E6%A0%88%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>NT 证明宏内核不必 Unix 形状：对象+IRP 同样能覆盖进程与设备。可移植课序要求会翻译，而不是背命令。不要写成哪边更好。与 <a href="/cs/lsm-selinux">SELinux</a>：MIC/完整性级别是另一套 MAC。</p><p>用户态子系统（Win32、WSL）说明 ABI 可叠在 NT 上——WSL2 实际是轻量 VM，接回 <a href="/cs/hypervisor-types">Hypervisor</a> 课。</p><p>实现上：IRP 可在驱动栈里同步或异步完成，取消路径复杂。作业对象限 CPU/内存，像 cgroup 的远亲。WSL2 用轻量 VM，对照的是 Hyper-V，不是 NT 原生 Unix。 读法上只引用<a href="/cs/rust-in-kernel">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「虚拟化与隔离进阶 / 容器与内核形态」课序里，对象是 <strong>Windows NT 对照</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有执行体组件。不保证 ReactOS。下一课课序封口：分布式 OS 直觉。</p><p>版本字段会变，课序钉的是机制对象「Windows NT 对照」，不是某一主线内核的结构体名。 后课默认：宏内核可以是 NT 对象模型。多机看起来像一台 OS 的限度，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NT：对象管理器、句柄、IRP。</li><li>与 Linux 的 VFS/cgroup/skb 是同问题不同切法。</li><li>分布式 OS 直觉是下一课。</li><li>出处：<em>Windows Internals</em>；Tanenbaum 对照。</li></ul>',11))])}const E=o(h,[["render",u]]);export{A as __pageData,E as default};
